"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["37649"],{74110(e,t,n){n.d(t,{Ay:()=>l,RM:()=>s});var o=n(74848),i=n(28453);let s=[];function a(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"a-brief-discussion-on-the-market-based-expression-of-national-economic-will",children:"A Brief Discussion on the Market-Based Expression of National Economic Will"})}),"\n",(0,o.jsxs)(t.blockquote,{children:["\n",(0,o.jsx)(t.p,{children:"2007/11/11 17:13:00"}),"\n"]}),"\n",(0,o.jsxs)("div",{style:{fontSize:"18px"},children:[(0,o.jsx)(t.p,{children:"Under planned economy conditions, the state's economic will can be proclaimed through multiple channels \u2014 the only thing lacking is marketization. Under market economy conditions, relying solely on hard measures such as administrative directives and policy interventions for regulation is clearly out of step with the times. Under market-based mechanisms, the deployment of state assets such as state-owned shares, foreign exchange reserves, and social security funds will inevitably embody the state's economic will. How to properly manage the relationships involved truly deserves serious exploration and research, as it concerns national economic security and the ultimate realization of the national economic development strategy."}),(0,o.jsx)(t.p,{children:"The state's economic will is not an impulsive whim, nor can it be based on short-term interests or moral impulses. The state's economic will must be built on the foresight, comprehensiveness, and systematicness of national strategy. Without foresight \u2014 thinking like a retail investor tailing a market maker, following other major powers' playbook \u2014 that is absolutely unacceptable. China is a major power, and its economic will must carry the bearing of a great nation. It must exert a Chinese-style gravitational pull on the global economic and political landscape, project a Chinese voice, and ultimately realize Chinese strategic objectives. Without comprehensiveness, it likewise won't work. The strategic orientation of China's national economic will must be comprehensive, not serving the interests of some particular time, place, or person. Its ultimate economic benefits must embody and realize the greatest and ultimate interests of the entire citizenry. As for systematicness, it means China's national economic will must and inevitably will manifest as an organic system with rigorous internal connections, multi-layered architecture, operability, and achievability."}),(0,o.jsx)(t.p,{children:'Currently, looking solely at the practical deployment of specific assets: state-owned shares have already become the single largest absolute controlling force in the stock market \u2014 the current index is entirely dominated by "China-prefixed" stocks. Social security funds will ultimately play an extremely important role in the transfer, reduction, and eventual operation of state-owned shares. And the establishment of China Investment Corporation has given the deployment of foreign exchange reserves in domestic and foreign capital markets a coordinated and strategically implicit significance that at least transcends mere swing-trading.'}),(0,o.jsx)(t.p,{children:"But the state's economic will is not merely reflected in specific stock operations or market-based transactions. More importantly, the expression of the state's economic will must absolutely not degenerate into a market-maker-style control operation \u2014 that would be extremely dangerous. The state's economic will should become an important \u2014 even the most important \u2014 component force in the market, but it cannot become the market's resultant force itself, much less the market's sole force. Once things evolve toward such a dangerous state, the so-called market-based expression of the state's economic will becomes empty rhetoric. Such \"market-based expression\" would instead become the very force that destroys the market's foundation."}),(0,o.jsx)(t.p,{children:"Furthermore, the state's economic will must also be expressed through the protection of national economic resources. National economic resources include not only narrowly defined physical and material resources, but also \u2014 under virtual economy conditions \u2014 all resources capable of generating market and capital effects. For example, China's excellent companies are the greatest economic resources of China's capital markets. How to rationally utilize these resources, rather than letting them be sold cheaply, drained abroad, or excessively exploited for short-term gains \u2014 this is a very real and heavily lesson-laden major issue."}),(0,o.jsx)(t.p,{children:"Standing at the level of capital deployment, the excessively market-oriented and excessively \"rat-infested\" funds can no longer independently serve as the economic embodiment of the state's will. A new absolute balancing force must be introduced to strengthen regulation. Since at the physical level, the state maintains absolute controlling stakes in industries vital to the people's livelihood, then at the virtual economy level, this absolute controlling nature is beyond question. That is to say, this absolute controlling nature must also necessarily include macro-level control over the overall trajectory of stock prices."}),(0,o.jsx)(t.p,{children:"As the state gradually withdraws from hard policy-level regulation, it must and inevitably will maintain an absolute regulatory force at the economic level. Otherwise, capital's challenge to policy would spiral into an uncontrollable situation \u2014 something completely at odds with China's national conditions. Strengthening the state's economic regulation encompasses both the physical and virtual dimensions. And strengthening the state's economic regulatory leadership position at the virtual level is a problem that must be resolved as soon as possible."})]})]})}function l(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(a,{...e})}):a(e)}},70862(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>d,frontMatter:()=>l,contentTitle:()=>r,toc:()=>h,assets:()=>c});var o=JSON.parse('{"id":"economics/statewill","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/economics/statewill.md","sourceDirName":"economics","slug":"/economics/statewill","permalink":"/en/economics/statewill","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"statewill","title":"","hide_table_of_contents":true,"sidebar_label":"A brief discussion on the market-based expression of national economic will (2007/11/11 17:13:00)"},"sidebar":"economicsSidebar","previous":{"title":"The 5-month moving average ambush script plays out as expected (2007/11/9 15:20:08)","permalink":"/en/economics/ma5ambush"},"next":{"title":"The 1000-point moderate decline target successfully achieved (2007/11/12 15:28:57)","permalink":"/en/economics/1000pointsfalling"}}'),i=n(74848),s=n(28453),a=n(74110);let l={id:"statewill",title:"",hide_table_of_contents:!0,sidebar_label:"A brief discussion on the market-based expression of national economic will (2007/11/11 17:13:00)"},r,c={},h=[...a.RM];function m(e){return(0,i.jsx)(a.Ay,{})}function d(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(m,{...e})}):m(e)}},28453(e,t,n){n.d(t,{R:()=>a,x:()=>l});var o=n(96540);let i={},s=o.createContext(i);function a(e){let t=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function l(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),o.createElement(s.Provider,{value:t},e.children)}}}]);